        tree.SetDimension(root, Dimension.Height, StyleLength.Points(500.0f));

        var rootChild0 = tree.CreateNode();
        tree.SetFlexBasis(rootChild0, StyleLength.Keyword(LayoutUnit.Stretch));
        tree.SetFlexWrap(rootChild0, Wrap.Wrap);
        tree.InsertChild(root, rootChild0, 0);

        var rootChild0Child0 = tree.CreateNode();
        tree.SetDimension(rootChild0Child0, Dimension.Width, StyleLength.Points(50.0f));
        tree.SetDimension(rootChild0Child0, Dimension.Height, StyleLength.Points(50.0f));
